mapper.insert:
INSERT INTO guitar_oss_cleanup_task (
    object_key, business_type, status, retry_count, next_retry_at, claim_version,
    processing_started_at, last_error
) VALUES (
    #{objectKey}, #{businessType}, #{status}, #{retryCount}, #{nextRetryAt}, #{claimVersion},
    #{processingStartedAt}, #{lastError}
)

mapper.select:
SELECT id, object_key, business_type, status, retry_count, next_retry_at, claim_version,
processing_started_at, last_error, create_time, update_time
FROM guitar_oss_cleanup_task WHERE status='PENDING' AND next_retry_at <= #{now}
ORDER BY next_retry_at ASC, id ASC LIMIT #{limit}

mapper.update:
UPDATE guitar_oss_cleanup_task SET status='PROCESSING', claim_version=claim_version+1,
processing_started_at=#{now}, update_time=#{now}
WHERE id=#{id} AND status='PENDING' AND next_retry_at <= #{now}
AND claim_version=#{expectedClaimVersion}

UPDATE guitar_oss_cleanup_task SET status='PENDING', next_retry_at=#{now}, processing_started_at=NULL,
last_error='OSS cleanup retry recovered stale task', update_time=#{now}
WHERE status='PROCESSING' AND processing_started_at < #{cutoff}

UPDATE guitar_oss_cleanup_task SET status='SUCCESS', processing_started_at=NULL,
last_error=NULL, update_time=#{now}
WHERE id=#{id} AND status='PROCESSING' AND claim_version=#{claimVersion}

UPDATE guitar_oss_cleanup_task SET status='PENDING', retry_count=#{retryCount}, next_retry_at=#{nextRetryAt},
processing_started_at=NULL, last_error=#{lastError}, update_time=#{now}
WHERE id=#{id} AND status='PROCESSING' AND claim_version=#{claimVersion}

UPDATE guitar_oss_cleanup_task SET status='FAILED', retry_count=#{retryCount}, processing_started_at=NULL,
last_error=#{lastError}, update_time=#{now}
WHERE id=#{id} AND status='PROCESSING' AND claim_version=#{claimVersion}
